const canvas = document.getElementById('outputCanvas');
const ctx = canvas.getContext('2d');
const regenerateBtn = document.getElementById('regenerateBtn');
const imageInput = document.getElementById('imageInput');

let selectedFiles = [];

imageInput.addEventListener('change', async () => {
  selectedFiles = Array.from(imageInput.files);
  await generateImage(selectedFiles);
});

regenerateBtn.addEventListener('click', async () => {
  if (selectedFiles.length > 0) {
    await generateImage(selectedFiles);
  }
});

async function generateImage(files) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const images = await Promise.all(
    files.map(file => loadImage(URL.createObjectURL(file)))
  );

  const tiles = [];
  for (let i = 0; i < images.length; i++) {
    const img = images[i];
    const imgCanvas = document.createElement('canvas');
    imgCanvas.width = 1080;
    imgCanvas.height = 1080;
    const imgCtx = imgCanvas.getContext('2d');
    imgCtx.drawImage(img, 0, 0, 1080, 1080);

    const isEven = i % 2 === 0;
    const tempTiles = [];

    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 4; x++) {
        const tileData = imgCtx.getImageData(x * 270, y * 270, 270, 270);
        if (isEven) {
          thresholdImageData(tileData);
        }
        tempTiles.push(tileData);
      }
    }

    shuffleArray(tempTiles);
    tiles.push({ isEven, tiles: tempTiles });
  }

  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      const index = y * 4 + x;
      for (let i = 0; i < tiles.length; i++) {
        const { isEven, tiles: tileSet } = tiles[i];
        const tile = tileSet[index];
        if (!isEven) {
          ctx.putImageData(tile, x * 270, y * 270);
        } else {
          const mask = tile;
          const original = ctx.getImageData(x * 270, y * 270, 270, 270);
          for (let j = 0; j < mask.data.length; j += 4) {
            if (mask.data[j] === 0) {
              original.data[j + 3] = 0; // transparent
            }
          }
          ctx.putImageData(original, x * 270, y * 270);
        }
      }
    }
  }

  applyGrain();
  applyGlitch();
  applyPixelation();
}

// === Visual Effect Functions ===
function applyGrain() {
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < imageData.data.length; i += 4) {
    const grain = (Math.random() - 0.5) * 40;
    imageData.data[i] += grain;
    imageData.data[i + 1] += grain;
    imageData.data[i + 2] += grain;
  }
  ctx.putImageData(imageData, 0, 0);
}

function applyGlitch() {
  const originalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const glitchData = ctx.createImageData(originalData);
  for (let y = 0; y < canvas.height; y++) {
    const offset = Math.floor(Math.random() * 10) - 5;
    for (let x = 0; x < canvas.width; x++) {
      const i = (y * canvas.width + x) * 4;
      const j = (y * canvas.width + ((x + offset + canvas.width) % canvas.width)) * 4;
      glitchData.data[i] = originalData.data[j];         // R
      glitchData.data[i + 1] = originalData.data[j + 1]; // G
      glitchData.data[i + 2] = originalData.data[j + 2]; // B
      glitchData.data[i + 3] = originalData.data[j + 3]; // A
    }
  }
  ctx.putImageData(glitchData, 0, 0);
}

function applyPixelation() {
  const pixelSize = 6;
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < canvas.height; y += pixelSize) {
    for (let x = 0; x < canvas.width; x += pixelSize) {
      const i = (y * canvas.width + x) * 4;
      const r = imageData.data[i];
      const g = imageData.data[i + 1];
      const b = imageData.data[i + 2];
      for (let py = 0; py < pixelSize; py++) {
        for (let px = 0; px < pixelSize; px++) {
          const ni = ((y + py) * canvas.width + (x + px)) * 4;
          imageData.data[ni] = r;
          imageData.data[ni + 1] = g;
          imageData.data[ni + 2] = b;
        }
      }
    }
  }
  ctx.putImageData(imageData, 0, 0);
}

// === Utility Functions ===
function loadImage(src) {
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.src = src;
  });
}

function shuffleArray(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
}

function thresholdImageData(imageData, threshold = 128) {
  for (let i = 0; i < imageData.data.length; i += 4) {
    const avg = (imageData.data[i] + imageData.data[i + 1] + imageData.data[i + 2]) / 3;
    const val = avg < threshold ? 0 : 255;
    imageData.data[i] = val;
    imageData.data[i + 1] = val;
    imageData.data[i + 2] = val;
  }
}
